        "translation": "治理國家與治軍的根本大道，在於依靠賢能人才與廣大人民；信任賢臣就像信任自己的心腹一樣親密無間，役使人民就像指揮自己的四肢一樣順暢自如，那麼一切決策謀略就絕不會出現任何遺漏偏差！指揮調動如同手臂指揮手指、肢體骨節自然相互救援，完全契合天地萬物的自然規律，其神妙精巧毫無任何破綻與間隙！",
        "analysis": "【題解與背景】\\n本段選自《三略》〈三略〉第 6 節。屬於古代兵家韜略代表性經典，記述先賢關於主張兵者國之大事、知己知彼、剛柔相濟與奇正相生之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「夫為國之道恃賢與民信賢如腹心使民如四肢則策無……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「夫」、「為」、「國」、「道」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《三略》知行合一與經世致用之哲理觀念，凝結古代軍事家對戰略決策、戰術變化與勝負規律之最高智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"
