      "order": 7,
      "canonicalText": "軍國之要，察眾心，施百務：危者，安之；懼者，歡之；叛者，還之；冤者，原之；訴者，察之；卑者，貴之；強者，抑之；敵者，殘之；貪者，豐之；欲者，使之；畏者，隱之；謀者，近之；讒者，覆之；毀者，復之；反者，廢之；橫者，挫之；滿者，損之；歸者，招之；服者，活之；降者，脫之。獲固，守之；獲阨，塞之；獲難，屯之；獲城，割之；獲地，裂之；獲財，散之。敵動，伺之；敵近，備之；敵強，下之；敵佚，去之；敵陵，待之；敵暴，緩之；敵悖，義之；敵睦，攜之。順舉挫之，因勢破之，放言過之，四網羅之。得而勿有，居而勿守，拔而勿久，立而勿取。為者則己，有者則士，焉知利之所在。彼為諸侯，己為天子，使城自保，令士自處。",
