      "canonicalText": "夫將帥者，必與士卒同滋味，而共安危，敵乃可加。故兵有全勝，敵有全因。昔者，良將之用，有饋簞醪者，使投諸河，與士卒同流而飲。夫一簞之醪，不能味一河之水，而三軍之士，思為致死者，以滋味之及己也。",
