      "canonicalText": "夫統軍持勢者，將也；制勝敗敵者，眾也。故亂將不可使保軍，乘眾不可使伐人。攻城不可拔，圍邑則不廢。二者無功，則士力疲憊；士力疲憊，則將孤眾悖，以守則不固，以戰則奔北，是謂老兵。兵老，則將威不行；將無威，則士卒輕刑；士卒輕刑，則軍失伍；軍失伍，則士卒逃亡；士卒逃亡，則敵乘利；敵乘利，則軍必喪。",
