      "id": "three-strategies_ch-1_p-17",
      "chapterId": "three-strategies_ch-1",
      "order": 17,
      "canonicalText": "軍讖曰：將能清，能靜，能平，能整，能受諫，能聽訟，能納人，能採言，能知國俗，能圖山川，能表險難，能制軍權。故曰：仁賢之智，聖明之慮，負薪之言，廊廟之語，興衰之事，將所宜聞。將者，能思士如渴，則策從焉。夫將拒諫，則英雄散；策不從，則謀士叛；善惡同，則功臣倦；專己，則下歸咎；自伐，則下少功；信讒，則眾離心；貪財，則奸不禁；內顧，則士卒淫。將有一，則眾不服；有二，則軍無式；有三，則下奔北；有四，則禍及國。",
