      "chapterId": "three-strategies_ch-1",
      "order": 18,
      "canonicalText": "軍讖曰：將謀欲密，士眾欲一，攻敵欲疾。將謀密，則姦心閉；士眾一，則軍心結；攻敵疾，則備不及設。軍有此三者，則計不奪。將謀洩，則軍無勢；外窺內，則禍不制；財入營，則眾奸會。將有此三者，軍必敗。將無慮，則謀士去；將無勇，則士卒恐；將妄動，則軍不重；將遷怒，則一軍懼。",
