      "chapterId": "three-strategies_ch-1",
      "order": 21,
      "canonicalText": "軍讖曰：香餌之下，必有死魚；重賞之下，必有勇夫。故禮者，士之所歸；賞者，士之所死。招其所歸，示其所死，則所求者至。故禮而後悔者，士不止；賞而後悔者，士不使。禮賞不倦，則士爭死。",
