      "chapterId": "three-strategies_ch-1",
      "order": 23,
      "canonicalText": "軍讖曰：用兵之要，必先察敵情，視其倉庫，度其糧食，卜其強弱，察其天地，伺其空隙。故國無軍旅之難，而運糧者，虛也；民菜色者，窮也。千里饋糧，士有飢色；樵蘇後爨，師不宿飽。夫運糧千里，無一年之食；二千里，無二年之食；三千里，無三年之食，是謂國虛。國虛，則民貧；民貧，則上下不親。敵攻其外，民盜其內，是謂必潰。",
