        "translation": "《軍讖》說道：統軍用兵的戰略樞要，務必首先深入偵察洞悉敵國實情：審視他的倉庫儲備，估算度量他的糧食存量，推算判斷他的軍力強弱，考察他的天時氣候與地理形勢，伺機尋找他的破綻空隙！如果一個國家平時境內本無任何外敵軍事入侵的急難，卻被迫長年累月四處轉運糧草後勤，這說明其國家內部財力極度空虛；如果老百姓面帶飢黃菜色，說明民間經濟極度貧窮困頓！遠徵千里向境外運送糧食，前線士卒臉上必定常帶飢餓之色；必須臨時砍伐柴草才能生火做飯（樵蘇後爨），部隊將士必定無法安枕飽食！轉運糧草達到一千里之遠，國家就根本存留不下一年的戰略存糧；轉運糧草達到二千里之遠，就存不下兩年的糧食；轉運達到三千里之遠，就存不下三年的糧食，這就叫做國庫空虛！國家空虛，百姓必定極端貧困；百姓貧困困頓，朝廷上下君民必定不再親睦同心！此時敵軍自外部大舉進攻，貧民百姓在內部挺而走險起義盜竊，這就叫做內外夾攻必定崩潰（必潰）！",
