      "readingAid": {
        "translation": "《軍讖》說道：地方豪強豪族聚集奸邪惡徒，雖然在朝堂沒有法定官位卻在鄉里尊崇無比，暗藏龐大黑惡勢力使人畏懼卻不顯山露水（威而不震）；宗族豪強如同葛藤葛藟一般盤根錯節蔓延勾連，在地方廣施小恩小惠培植私恩，架空剝奪在位官員的法定治理權力，肆無忌憚欺凌侵辱底層貧苦平民；導致舉國上下民怨沸騰喧譁抗議，朝廷大臣卻受其收買庇護隱瞞實情不肯上報皇帝，這就叫做動搖國本的動亂之根（亂根）！",
        "analysis": "【題解與背景】\\n本段選自《三略》〈三略〉第 27 節。屬於古代兵家韜略代表性經典，記述先賢關於主張兵者國之大事、知己知彼、剛柔相濟與奇正相生之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「軍讖曰強宗聚姦無位而尊威而不震葛藟相連種德立……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「軍」、「讖」、「強」、「宗」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《三略》知行合一與經世致用之哲理觀念，凝結古代軍事家對戰略決策、戰術變化與勝負規律之最高智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"
      }
