      "readingAid": {
        "translation": "《軍讖》上說：如果諸侯、藩鎮或權臣的勢力（枝葉）過於強大，他們互相勾結、盤踞在國家的要害權位上；導致原本地位卑賤的人反過來欺凌尊貴的君主；這種情況時間一久，他們的勢力就會越來越大。如果最高統治者因為心慈手軟或猶豫不決而不敢果斷廢除他們，國家最終必將遭受覆滅的敗局。",
        "analysis": "【訓詁與名物】「枝葉」比喻諸侯、藩鎮、宗室或權臣。相對於君主（主幹）而言。「比周」互相勾結、拉幫結派。「居勢」佔據權力的高位或戰略要地。「陵」欺凌、僭越。「廢」廢除、剷除。「敗」失敗、滅亡。\\n【章法與結構】本段運用了「強枝弱幹」的植物學隱喻，來探討中央與地方（或君權與相權）的政治平衡問題。文章依循著權力失衡的發展軌跡進行敘述：從勢力的膨脹（枝葉強大），到結黨營私（比周居勢），再到徹底的僭越（卑賤陵貴）；最後將責任歸咎於最高統治者的姑息養奸（上不忍廢），並發出亡國的警告（國受其敗）。\\n【思想與義理】此段精準預言了中國歷史上反覆出現的「尾大不掉」與「藩鎮割據」現象。在專制體制下，中央集權（主幹）必須擁有絕對的優勢。一旦地方將領或朝中權臣（枝葉）掌握了過多的軍政資源，他們必然會結成利益聯盟，最終威脅甚至取代皇權。兵家強烈警告統治者，在面對權力被蠶食時，絕不能有任何「婦人之仁（不忍廢）」，必須在毒瘤尚未徹底做大之前果斷切除，否則整個國家體制都會被其拖垮。"
      }
