      "canonicalText": "軍讖曰：姦雄相稱，障蔽主明。毀譽並興，壅塞主聰，各阿所私，令主失忠。故主察異言，乃觀其萌。主聘儒賢，姦雄乃遯。主任舊齒，萬事乃理。主聘巖穴，士乃得實。謀及負薪，功乃可述。不失人心，德乃洋溢。",
