      "readingAid": {
        "translation": "《軍讖》說道：奸邪奸雄互相吹捧吹噓，徹底遮蔽了明君的明察之眼；惡意毀謗與虛偽讚譽同時泛濫四起，徹底堵塞了君王的聰敏耳目；奸臣們各自偏袒迎合自己的私人利益，導致君王徹底喪失了忠貞不渝的賢臣！因此英明君主必須明察傾聽各種不同意見與反對聲音（察異言），從而敏銳洞察動亂奸邪的最初萌芽！君王若能隆重禮聘德才兼備的儒學賢士，奸雄奸佞自然逃遁隱匿；君王若能信任重用德高望重的老成舊臣（舊齒），天下萬般政務自然井井有條；君王若能親自聘請隱居深山巖穴之中的隱士大賢，朝廷才能獲得名副其實的真正棟樑；決策謀劃若能放下身段諮詢底層樵夫百姓（負薪之言），所建立的歷史功勳才能名垂青史大放光彩！只要始終如一永不喪失天下民心，君王的浩瀚盛德自然洋溢充盈遍佈四海八荒！",
        "analysis": "【題解與背景】\\n本段選自《三略》〈三略〉第 33 節。屬於古代兵家韜略代表性經典，記述先賢關於主張兵者國之大事、知己知彼、剛柔相濟與奇正相生之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「軍讖曰姦雄相稱障蔽主明毀譽並興壅塞主聰各阿所……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「軍」、「讖」、「姦」、「雄」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《三略》知行合一與經世致用之哲理觀念，凝結古代軍事家對戰略決策、戰術變化與勝負規律之最高智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"
      }
