      "id": "three-strategies_ch-1_p-34",
      "chapterId": "three-strategies_ch-1",
      "order": 34,
      "canonicalText": "夫三皇無言，而化流四海，故天下無所歸功。帝者，體天則地，有言有令，而天下太平：君臣讓功，四海化行，百姓不知其所以然，故使臣不待禮賞，有功美而無害。王者，制人以道，降心服志，設矩備衰，四海會同，王職不廢，雖有甲兵之備，而無戰鬥之患；君無疑於臣，臣無疑於主，國定民安，臣以義退，亦能美而無害。霸者，制士以權，結士以信，使士以賞：信衰則士疏，賞虧則士不用命。",
