      "readingAid": {
        "translation": "《軍勢》上說：軍中必須嚴格禁止巫師和祝告者活動，絕不允許他們為軍官和士兵占卜預測戰爭的吉凶勝負。",
        "analysis": "【訓詁與名物】「巫祝」古代從事降神、占卜、祈禱的宗教迷信職業者。「卜問」透過占卜來詢問未來。「吉凶」戰爭的勝敗禍福。\\n【章法與結構】本段是一條極其簡潔且堅決的軍法禁令。前半句「禁巫祝」直接下達封殺令；後半句「不得為吏士...」則詳細說明瞭封殺的具體行為與對象，毫無轉圜的餘地。\\n【思想與義理】這段記載展現了中國古代兵家高度的理性精神與唯物史觀。在充滿不確定性與死亡恐懼的戰場上，士兵極容易陷入迷信，尋求神鬼的心理慰藉。然而，一旦「巫祝」用占卜的結果（特別是凶兆）來暗示戰爭的勝負，就會在瞬間摧毀全軍的士氣，甚至引發集體恐慌或營嘯。因此，《吳子》、《孫子》等兵法都將「禁祥去疑（禁止迷信、消除疑慮）」視為治軍的鐵律。戰爭的勝負必須建立在實力與謀略之上，絕不能交由虛無縹緲的神鬼占卜來決定。"
      }
