      "readingAid": {
        "translation": "君主絕對不能沒有恩德，如果沒有恩德，臣子就會背叛；君主也絕對不能沒有威嚴，如果沒有威嚴，就會失去統治的權力。臣子絕對不能沒有道德，如果沒有道德，就無法忠誠地侍奉君主；臣子在職位上也絕對不能沒有威信，如果沒有威信，國家的行政力量就會衰弱；但是，如果臣子的威權過大甚至超越了君主，他自己就會招致殺身之禍。",
        "analysis": "【訓詁與名物】「德」恩德、道德修養。「威」威嚴、權力、威信。「權」君主的統治權。「事君」侍奉君主。「身蹶」蹶讀ㄐㄩㄝˊ，跌倒、傾覆，指招致殺身之禍。\\n【章法與結構】這是一段邏輯極其嚴密的政治權力學論述。文章採取了「君與臣」雙線並行的對稱結構：先論「君之德與威」，再論「臣之德與威」。每一層都運用了「不可以無...無則...」的假設推論句式，將德與威缺失的後果剖析得條理分明。最後在論述「臣之威」時，突然補上一句「威多則身蹶」，打破了平衡，點出了臣權不可僭越君權的終極紅線。\\n【思想與義理】此段深刻體現了中國古代政治哲學中「德威並濟」與「君臣倫理」的思想。對於君主而言，「德」是凝聚人心的引力（防臣叛），「威」是維持秩序的壓力（防失權），兩者缺一不可。對於臣子而言，「德」是政治合法性的來源（事君），「威」是執行職務的必要工具（防國弱）；然而，專制體制對臣子的威權又有一種天然的恐懼與防範——臣子的威權一旦膨脹到威脅皇權的警戒線，必然會引發君主的清洗（身蹶）。這是一種充滿了平衡、博弈與殘酷現實的政治生存法則。"
      }
