      "canonicalText": "聖人體天，賢人法地，智者師古。是故三略為衰世作：上略設禮賞，別姦雄，著成敗；中略差德行，審權變；下略陳道德，察安危，明賊賢之咎。故人主深曉上略，則能任賢擒敵；深曉中略，則能御將統眾；深曉下略，則能明盛衰之源，審治國之紀。",
