      "readingAid": {
        "translation": "能夠保全國家政權（社稷），並且廣泛網羅天下英雄人才的戰略，這屬於《中略》所探討的權力運用態勢，因為這種權勢的運作必須是隱密而不顯露的。",
        "analysis": "【訓詁與名物】「存社稷」保全國家政權。社稷，土神與穀神，代指國家。「羅英雄」網羅天下英雄人才。「中略」《三略》分為上、中、下三略，此指《中略》的篇章內容。「勢」權勢、戰略態勢。「祕」隱密、不張揚。\\n【章法與結構】本段文字為《三略》一書體例上的自我註解。前兩句（存社稷，羅英雄）概括了治國平天下的兩大核心任務；第三句（中略之勢也）點明這些內容在全書中的學術歸屬；最後以「故勢祕焉」作結，點出這種政治戰略的最高操作原則。\\n【思想與義理】此段揭示了古代政治與軍事戰略中「隱密性（祕）」的重要性。無論是保衛國家政權，還是招攬天下英才，這些都是涉及國家最高機密與核心利益的重大戰略。高明的統治者在佈局這些大戰略時，絕不能大張旗鼓、四處張揚，而必須將自己的真實意圖深深隱藏起來（勢祕焉），在暗中積蓄力量、羅致人才。這種「大象無形」的政治權謀，與前文提到的「守微」思想一脈相承。"
      }
