      "canonicalText": "捨己而教人者逆，正己而化人者順。逆者亂之招，順者治之要。道、德、仁、義、禮五者，一體也。道者人之所蹈，德者人之所得，仁者人之所親，義者人之所宜，禮者人之所體，不可無一焉。故夙興夜寐，禮之制也；討賊報讎，義之決也；惻隱之心，仁之發也；得己得人，德之路也；使人均平，不失其所，道之化也。",
