      "id": "three-strategies_ch-1_p-52",
      "chapterId": "three-strategies_ch-1",
      "order": 52,
      "canonicalText": "千里迎賢其路遠，致不肖其路近。是以明君舍近而收遠，故能全功尚人，而下盡力。",
      "sentenceIds": [
        "three-strategies_ch-1_p-52_s-1",
        "three-strategies_ch-1_p-52_s-2"
      ],
      "sourceRefs": [
        {
          "label": "經文底本",
          "edition": "dianji.fun",
          "url": "https://ctext.org/three-strategies/zh"
        },
        {
          "label": "維基文庫《三略》全文",
          "edition": "維基文庫繁體全文頁（人工開啟核實 2026-08-14）",
          "url": "https://zh.wikisource.org/wiki/%E4%B8%89%E7%95%A5"
        }
      ],
      "readingAid": {
        "translation": "跋涉千里去迎接真正的賢才，這條路雖然遙遠艱難；但要招攬那些沒有才能的庸才（不肖），這條路卻很近很容易。因此，英明的君主寧可捨棄眼前容易得到的庸才，也要不辭辛勞地去遠方收攬真正的賢才。正因為如此，明君才能成就完美的功業，並在用人上超越常人，而下面的臣民也會因為佩服君主的求賢若渴而拼盡全力效勞。",
        "analysis": "【訓詁與名物】「迎賢」迎接、招攬賢能之士。「致」招致、引來。「不肖」不才、沒有才能或品德的人。「舍」同「捨」，捨棄。「全功」成就完美、保全功業。「尚」超越、高出。「下」指臣子與百姓。\\n【章法與結構】本段運用了「遠與近」、「難與易」的空間隱喻來探討人才戰略。前兩句以「迎賢路遠」與「致不肖路近」形成強烈對比，點出尋找真人才的艱難與庸才的氾濫；第三句（舍近而收遠）點出明君的艱難抉擇與政治魄力；最後一句（全功尚人，下盡力）則揭示了這種艱辛付出所帶來的豐厚政治回報。\\n【思想與義理】這是一段關於「求賢若渴」的政治經驗總結。在任何時代，真正的頂尖人才（賢）都是稀缺資源，往往隱居於草野或遠方，統治者必須放下身段、付出巨大的誠意與代價（千里迎賢）才能得到。而那些阿諛奉承、尸位素餐的庸才（不肖），卻總是圍繞在權力中心附近（路近），唾手可得。昏庸的君主貪圖安逸，往往就近任用庸才，導致國政敗壞；而明君則深知「人才投資」的價值，他們捨近求遠的求賢姿態，不僅能獲得治國的棟樑，更是一種極佳的政治宣傳，能激發全社會的報國熱情（下盡力）。"
      }
