      "canonicalText": "廢一善則眾善衰，賞一惡則眾惡歸。善者得其佑，惡者受其誅，則國安而眾善至。眾疑無定國，眾惑無治民，疑定惑還，國乃可安。一令逆則百令失，一惡失則百惡結。故善施於順民，惡加於兇，則令行而無怨。",
