        "translation": "品行高潔清白正直的清白之士，絕不可能單純用高官厚祿來收買拉攏；堅守氣節深明大義的節義之士，也絕不可能用嚴刑峻法殘酷威脅來迫使其屈服！所以英明君主在尋求招攬天下大賢之際，務必深入觀察了解他們內心真正的精神追求從而採取合適的感召方式：要招致高潔清白的士人，君主必須修養自身崇高的禮節禮儀；要招致深明節義的志士，君主必須弘揚踐行天下至高的大道公理！只有這樣天下大賢才能被感召前來輔佐，而君王的千古聖名才能萬古長存流傳後世！",
