      "canonicalText": "聖王之用兵，非樂之也，將以誅暴討亂也。夫以義誅不義，若決江河而溉爝火，臨不測而擠欲墜，其克必矣。所以優遊恬淡而不進者，重傷人物也。夫兵者，不祥之器，天道惡之，不得已而用之，是天道也。",
